#include <core.p4>
#include <v1model.p4>

typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

header ethernet_t {
    macAddr_t dstAddr;
    macAddr_t srcAddr;
    bit<16>   etherType;
}

header ipv4_t {
    bit<4>    version;
    bit<4>    ihl;
    bit<8>    diffserv;
    bit<16>   totalLen;
    bit<16>   identification;
    bit<3>    flags;
    bit<13>   fragOffset;
    bit<8>    ttl;
    bit<8>    protocol;
    bit<16>   hdrChecksum;
    ip4Addr_t srcAddr;
    ip4Addr_t dstAddr;
}

struct metadata {}

struct headers {
    ethernet_t   ethernet;
    ipv4_t       ipv4;
}

parser MyParser(packet_in b, out headers h, inout metadata m, inout standard_metadata_t sm) {
    state start {
        transition parse_ethernet;
    }
    state parse_ethernet {
        b.extract(h.ethernet);
        transition select(h.ethernet.etherType) {
            16w0x800 : parse_ipv4;
            default : accept;
        }
    }
    state parse_ipv4 {
        b.extract(h.ipv4);
        transition accept;
    }
}

control VerifyChecksum(inout headers h, inout metadata m) {
    apply { }
}

control ComputeChecksums(inout headers h, inout metadata m) {
    apply { }
}

action drop() {
    mark_to_drop(sm);
}

action forward(egressSpec_t port) {
    sm.egress_spec = port;
}

table MyTable(inout headers h, inout metadata m, inout standard_metadata_t sm) {
    key = {
        h.ipv4.dstAddr : exact;
    }
    actions = {
        forward;
        drop;
    }
    size = 1024;
    default_action = drop();
}

control MyVerifyChecksum(inout headers h, inout metadata m) {
    apply { }
}

control MyIngress(inout headers h, inout metadata m, inout standard_metadata_t sm) {
    action drop() {
        mark_to_drop(sm);
    }
    table my_table {
        MyTable(h, m, sm);
    }
    apply {
        if ( !(my_table.apply()) ) {
            drop();
        }
    }
}

control MyEgress(inout headers h, inout metadata m, inout standard_metadata_t sm) {
    apply { }
}

control MyComputeChecksum(inout headers h, inout metadata m) {
    apply { }
}

control MyDeparser(packet_out b, in headers h) {
    apply {
        b.emit(h.ethernet);
        b.emit(h.ipv4);
    }
}

V1Switch(MyParser(),
         MyVerifyChecksum(),
         MyIngress(),
         MyEgress(),
         MyComputeChecksum(),
         MyDeparser()) main;

