        mark_to_drop(stdmeta);
    }
    action hash_ipv4(bit<32> src_ip, bit<32> dst_ip, bit<8> protocol) {
        bit<32> hash = ((src_ip >> 16) ^ (dst_ip >> 16)) & 0xFF;
        hash = (hash << 8) | (((src_ip >> 8) ^ (dst_ip >> 8)) & 0xFF);
        hash = (hash << 8) | ((src_ip ^ dst_ip) & 0xFF);
        hash = (hash << 8) | protocol;
        stdmeta.egress_spec = hash % 5;
    }
    table rewrite_table {
        key = {
            hdr.ipv4.isValid(): exact;
        }
        actions = {
            hash_ipv4;
            drop;
        }
        size = 1024;
        default_action = drop();
    }
    apply {
        if (hdr.ipv4.isValid()) {
            rewrite_table.apply();
        } else {
            drop();
        }
    }
