struct metadata {}

struct control_plane_metadata {}

struct parser_state {
    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        extract(ethernet) @ Ethernet;
        transition select(ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            TYPE_ARP: accept;
            default: reject;
        }
    }

    state parse_ipv4 {
        apply {
            hdr.ipv4.isValid = true;
        }
        transition accept;
    }
}

parser MyParser(packet_in packet,
                out headers hdr,
                inout metadata meta,
                inout standard_metadata_t stdmeta) {
    state start;
    action drop() {
        mark_to_drop(stdmeta);
    }
    action accept() {
        set_valid(stdmeta);
    }
    table t_ingress {
        key = {
            hdr.ethernet.dstAddr: exact;
        }
        actions = {
            drop;
            accept;
        }
        size = 128;
        default_action = drop();
    }
    apply {
        switch (state) {
            case start:
                t_ingress.apply();
                goto end;
        }
    end: ;
    }
}

