    apply {
    }
}

control MyIngress(inout headers hdr,
                  inout metadata meta,
                  inout standard_metadata_t stdmeta) {
    action drop() {
        mark_to_drop(stdmeta);
    }
    action forward(egressSpec_t port) {
        stdmeta.egress_spec = port;
    }
    table t_routing {
        key = {
            hdr.ipv4.srcAddr: exact;
        }
        actions = {
            forward;
            drop;
        }
        size = 1024;
        default_action = drop();
    }
    apply {
        t_routing.apply();
    }
}

