control Forwarding(inout headers hdr, inout metadata meta) {
    apply {
        @name("forward") action fwd(egressSpec_t port) = update_field(standard_metadata.egress_spec, port);
        table t0 {
            key = {
                hdr.ipv4.dstAddr : exact;
            }
            actions = {
                fwd;
            }
            size = 1024;
            default_action = fwd(4);
