control ComputeChecksums(inout headers hdr, inout metadata meta) {
    apply {
        update_checksum(
            Ethernet,
            { hdr.ipv4.isValid(),
              hdr.ipv4.version,
              hdr.ipv4.ihl,
              hdr.ipv4.diffserv,
              hdr.ipv4.totalLen,
              hdr.ipv4.identification,
              hdr.ipv4.flags,
              hdr.ipv4.fragOffset,
              hdr.ipv4.ttl,
              hdr.ipv4.protocol,
              hdr.ipv4.srcAddr,
              hdr.ipv4.dstAddr },
            hdr.ipv4.hdrChecksum,
            HashAlgorithm.csum16);

        update_checksum(
            IPv4,
            { hdr.tcp.isValid(),
              hdr.tcp.version,
              hdr.tcp.ihl,
              hdr.tcp.dscp,
              hdr.tcp.ecn,
              hdr.tcp.totalLen,
              hdr.tcp.identification,
              hdr.tcp.flags,
              hdr.tcp.fragOffset,
              hdr.tcp.ttl,
              hdr.tcp.protocol,
              hdr.tcp.srcAddr,
              hdr.tcp.dstAddr,
              hdr.tcp.pad1,
              hdr.tcp.options },
            hdr.tcp.hdrChecksum,
            HashAlgorithm.csum16);
    }
}

control UpdateQueueDelay(inout headers hdr, inout metadata meta) {
    apply {
        if (hdr.ipv4.isValid()) {
            meta.queue_delay += 1;
        }
    }
}

control Deparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
        packet.emit(hdr.ipv4);
        packet.emit(hdr.tcp);
