#include <core.p4>
#include <v1model.p4>

const bit<9> TYPE_IPV4 = 0x800;
const bit<9> TYPE_ARP = 0x806;
const bit<32> IP_SRC_ADDR = 0x0A00000F;
const bit<32> IP_DST_ADDR = 0x0A000007;

typedef bit<9> type_t;
typedef bit<48> macaddr_t;
typedef bit<32> ipv4_t;

header ethernet_t {
    macaddr_t dstAddr;
    macaddr_t srcAddr;
    type_t   etherType;
}

header arp_t {
    bit<16> hwtype;
    bit<16> proto;
    bit<8>  hwlen;
    bit<8>  protolen;
    bit<16> opcode;
    macaddr_t sha;
    ipv4_t spa;
    macaddr_t tha;
    ipv4_t tpa;
}

header ipv4_t {
    bit<4>  version;
    bit<4>  ihl;
    bit<8>  diffserv;
    bit<16> totalLen;
    bit<16> identification;
    bit<3>  flags;
    bit<13> fragOffset;
    bit<8>  ttl;
    bit<8>  protocol;
    bit<16> hdrChecksum;
    ipv4_t srcAddr;
    ipv4_t dstAddr;
}

struct metadata {
}

struct headers {
    ethernet_t     ethernet;
    ipv4_t         ipv4;
    arp_t          arp;
}

parser MyParser(packet_in b, out headers h, inout metadata m) {
    state start {
        transition parse_ethernet;
    }
    state parse_ethernet {
        b.extract(h.ethernet);
        transition select(h.ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            TYPE_ARP: parse_arp;
            default: accept;
        }
    }
    state parse_ipv4 {
        b.extract(h.ipv4);
        transition accept;
    }
    state parse_arp {
        b.extract(h.arp);
        transition accept;
    }
}

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}

control MyIngress(inout headers hdr, inout metadata meta, inout standard_metadata_t stdmeta) {
    action drop() {
        mark_to_drop(stdmeta);
    }

    table tcp_filter {
        key = {
            hdr.ipv4.dstAddr : exact;
            hdr.ipv4.srcAddr : exact;
            hdr.ipv4.protocol : exact;
            hdr.ipv4.dstPort : exact;
        }
        actions = {
            drop;
        }
        size = 1024;
        default_action = drop();
    }

    apply {
        if (hdr.ipv4.isValid()) {
            tcp_filter.apply();
        }
    }
}

control MyEgress(inout headers hdr, inout metadata meta, inout standard_metadata_t stdmeta) {
    apply {  }
}

control MyComputeChecksum(inout headers hdr, inout metadata meta) {
    apply {  }
}

control MyDeparser(packet_out b, in headers hdr) {
    apply {
        b.emit(hdr.ethernet);
        b.emit(hdr.ipv4);
        b.emit(hdr.arp);
    }
}

V1Switch(MyParser(),
         MyVerifyChecksum(),
         MyIngress(),
         MyEgress(),
         MyComputeChecksum(),
         MyDeparser()) main;

#include <core.p4>
#include <v1model.p4>

const bit<9> TYPE_IPV4 = 0x800;
const bit<9> TYPE_ARP = 0x806;
const bit<9> TYPE_ICMP = 0x8;

typedef bit<32> macaddr;
typedef bit<48> etherMac;

header ethernet_t {
    macaddr dstAddr;
    macaddr srcAddr;
    bit<16> etherType;
}

struct headers {
    ethernet_t ethernet;
}

parser MyParser(packet_in packet, out headers hdr, inout metadata meta, inout standard_metadata_t stdmeta) {
    state start {
        transition parse_ethernet;
    }
    state parse_ethernet {
        packet.extract(hdr.ethernet);
        transition select(hdr.ethernet.etherType) {
            TYPE_IPV4: parse_ipv4;
            TYPE_ARP: accept;
            default: reject;
        }
    }
    state parse_ipv4 {
        packet.extract(hdr.ipv4);
        transition accept;
    }
}

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {}
}

control MyIngress(inout headers hdr, inout metadata meta, inout standard_metadata_t stdmeta) {
    action drop() {
        mark_to_drop(stdmeta);
    }
    table t_arp {
        key = {
            hdr.ipv4.dstAddr: lpm;
        }
        actions = {
            drop;
        }
        size = 1024;
        default_action = drop();
    }
    table t_icmp {
        key = {
            hdr.ipv4.srcAddr: exact;
        }
        actions = {
            drop;
        }
        size = 1024;
        default_action = drop();
    }
    action forward_l2(macaddr addr) {
        hdr.ethernet.dstAddr = addr;
        update_checksum(
            Ethernet,
            { hdr.ethernet.dstAddr, hdr.ethernet.srcAddr, hdr.ethernet.etherType },
            hdr.ethernet.isValid
        );
    }
    action forward_l3(bit<32> addr) {
        hdr.ipv4.ttl = hdr.ipv4.ttl - 1;
        hdr.ipv4.srcAddr = addr;
        update_checksum(
            IPv4,
            { hdr.ipv4.version, hdr.ipv4.ihl, hdr.ipv4.diffserv, hdr.ipv4.totalLen, hdr.ipv4.identification, hdr.ipv4.flags, hdr.ipv4.fragOffset, hdr.ipv4.ttl, hdr.ipv4.protocol, hdr.ipv4.srcAddr, hdr.ipv4.dstAddr },
            hdr.ipv4.isValid
        );
    }
    action send_arp(macaddr addr) {
        hdr.ethernet.etherType = TYPE_ARP;
        hdr.arp.opcode = 1;
        hdr.arp.senderHwAddress = hdr.ethernet.srcAddr;
        hdr.arp.targetHwAddress = addr;
        hdr.arp.senderProtoAddress = hdr.ipv4.srcAddr;
        hdr.arp.targetProtoAddress = hdr.ipv4.dstAddr;
        update_checksum(
            Arp,
            { hdr.arp.hwType, hdr.arp.protoType, hdr.arp.hwSize, hdr.arp.protoSize, hdr.arp.opcode, hdr.arp.senderHwAddress, hdr.arp.senderProtoAddress, hdr.arp.targetHwAddress, hdr.arp.targetProtoAddress },
            hdr.arp.isValid
        );
    }
    action send_icmp(bit<32> addr) {
        hdr.ipv4.protocol = 1;
        hdr.icmp.type = 8;
        hdr.icmp.code = 0;
        hdr.icmp.checksum = 0;
        hdr.icmp.id = hdr.ipv4.identification;
        hdr.icmp.seqNum = hdr.ipv4.fragmentOffset;
        hdr.icmp.data = 0;
        update_checksum(
            Icmp,
            { hdr.icmp.type, hdr.icmp.code, hdr.icmp.checksum, hdr.icmp.id, hdr.icmp.seqNum, hdr.icmp.data },
            hdr.icmp.isValid
        );
        hdr.ipv4.dstAddr = addr;
        update_checksum(
            IPv4,
            { hdr.ipv4.version, hdr.ipv4.ihl, hdr.ipv4.diffserv, hdr.ipv4.totalLen, hdr.ipv4.identification, hdr.ipv4.flags, hdr.ipv4.fragOffset, hdr.ipv4.ttl, hdr.ipv4.protocol, hdr.ipv4.srcAddr, hdr.ipv4.dstAddr },
            hdr.ipv4.isValid
        );
    }
    table t_forward {
        key = {
            hdr.ipv4.dstAddr: exact;
        }
        actions = {
            forward_l2;
            send_arp;
            send_icmp;
        }
        size = 1024;
        default_action = drop();
    }
    apply {
        if (hdr.ipv4.isValid && hdr.ipv4.protocol == 1) {
            t_icmp.apply();
        } else if (hdr.ipv4.isValid && hdr.ipv4.protocol == 6) {
            t_forward.apply();
        } else {
            drop();
        }
    }
}

control MyEgress(inout headers hdr, inout metadata meta, inout standard_metadata_t stdmeta) {
    apply {}
}

control MyComputeChecksum(inout headers hdr, inout metadata meta) {
    apply {}
}

control MyDeparser(packet_out packet, in headers hdr) {
    apply {
        packet.emit(hdr.ethernet);
    }
}

V1Switch(MyParser(),
         MyVerifyChecksum(),
         MyIngress(),
         MyEgress(),
         MyComputeChecksum(),
         MyDeparser()) main;

