typedef bit<9>  egressSpec_t;
typedef bit<48> macAddr_t;
typedef bit<32> ip4Addr_t;

struct headers {
    ethernet_h_t ethernet;
    ipv4_h_t ipv4;
}

parser MyParser(packet_in b, out headers hdr, inout metadata meta, inout standard_metadata_t stdmeta) {
    state start {
        transition parse_ethernet;
    }
    state parse_ethernet {
        hdr.ethernet = EthernetParser();
        transition select(hdr.ethernet.etherType) {
            0x0800: parse_ipv4;
            default: accept;
        }
    }
    state parse_ipv4 {
        hdr.ipv4 = Ipv4Parser();
        transition accept;
    }
}

control VerifyChecksum(inout headers hdr, inout metadata meta) {
    apply {}
}

control ComputeChecksum(inout headers hdr, inout metadata meta) {
    apply {}
}

control UpdateChecksum(inout headers hdr, inout metadata meta) {
    apply {}
}

control Deparser(packet_out b, in headers hdr) {
    apply {
        Bit#(48) pad = '1;
        b.emit(hdr.ethernet);
        b.emit(hdr.ipv4);
    }
}

V1Switch(MyParser(), VerifyChecksum(), UpdateChecksum(), ComputeChecksum(), Deparser()) main;
